340	// A snapshot may restore the full current status after more than one attempt,
341	// for both waiting and successful messages; the restored record then behaves
342	// exactly like one that had gone through those attempts live.
343	func TestStateRestoresMultiAttemptStatus(t *testing.T) {
344		t.Run("waiting after three attempts", func(t *testing.T) {
345			dir := t.TempDir()
